def normalize_poem_from_filename(file_name: str, prefixes: list[str]) -> str:
    name = re.sub(r"\.[A-Za-z0-9]+$", "", file_name).strip()
    for prefix in prefixes:
        if name.upper().startswith(prefix.upper()):
            name = name[len(prefix):].strip(" -")
            break
    name = re.sub(r"\s+\(\d+\)$", "", name).strip()
    return name


def make_record(
    release_year: str,
    author_name: str,
    book_shortener: str,
    file_name: str,
    link_url: str,
    folder_title: str,
    folder_link: str,
    prefixes: list[str],
    book_title: str = "",
) -> dict[str, str]:
    return {
        "asset_key": link_url or file_name,
        "release_year": release_year,
        "author_name": author_name,
        "book_shortener": book_shortener,
        "book_title": book_title,
        "poem_title": normalize_poem_from_filename(file_name, prefixes),
        "excerpt": "",
        "file_name": file_name,
        "link_url": link_url,
        "low_res_file_name": "",
        "low_res_link_url": "",
        "folder_link": folder_link,
        "file_type": "QI",
        "file_type_helper": "QI",
        "book_release_catalog": "",
        "graphic_made_status": "Y",
        "approved_for_quote_image": "Y",
        "used_status": "",
        "notes": f"manual_drive_catchup:{folder_title}",
        "alternate_filename": "",
        "source_row_number": "",
        "source_row_numbers": "",
        "excerpt_id": "",
        "excerpt_ids": "",
        "source_row_count": 0,
        "release_year_values": release_year,
        "any_graphic_made_status_y": "Y",
        "any_approved_for_quote_image_y": "Y",
        "missing_core_fields": "",
    }


