def main() -> None:
    parser = argparse.ArgumentParser(description="Merge a verified recent Drive catch-up into qi_catalog_match.db")
    parser.add_argument("--catalog-db-path", type=Path, default=DEFAULT_CATALOG_DB_PATH)
    parser.add_argument("--output-db", type=Path, default=DEFAULT_OUTPUT_DB_PATH)
    args = parser.parse_args()

    catalog_conn = sqlite3.connect(args.catalog_db_path)
    output_conn = sqlite3.connect(args.output_db)
    try:
        books, _ = load_catalog_books(catalog_conn)
        poems = load_catalog_poems(catalog_conn)
        # Keep only assets that are not already present by asset key.
        existing = {
            row[0]
            for row in output_conn.execute("SELECT asset_key FROM image_assets").fetchall()
        }
        to_insert = [record for record in RECENT_ASSETS if record["asset_key"] not in existing]
        insert_records(output_conn, to_insert, books, poems)
        output_conn.commit()
        print(f"Inserted {len(to_insert)} recent Drive assets into {args.output_db}")
    finally:
        catalog_conn.close()
        output_conn.close()


if __name__ == "__main__":
    main()
